import { boxReference } from './box-queue.js';
import { eventFacts, eventOrdinal, activityRange, settlementFacts } from './facts.js';
import { boxLeg, BOX_RESULTS, knownEvents } from './feeds.js';
import { previousEvents } from './event-store.js';
import { revealedEntries } from './tickets.js';
import { playerAddress, uint } from './state.js';
import { coinflipDay } from './games.js';
import { ChainDataError } from './client.js';

export async function levelAt(s, blockNumber, signal) {
  const prior = await previousEvents(s.client, 'GAME', 'Advance', { blockNumber, logIndex: Number.MAX_SAFE_INTEGER }, { signal });
  return Number(prior.at(-1)?.args.lvl ?? 0);
}
// A settled bet's word, from its DegeneretteBetPlaced (same player/index/betId; often an earlier day).
async function placementWord(s, resolved, events, signal) {
  const a = resolved.args;
  const same = e => e.name === 'DegeneretteBetPlaced' && String(e.args.index) === String(a.index) && String(e.args.betId) === String(a.betId);
  const local = events.filter(same).at(-1);
  if (local) return local.args.packed;
  const prior = await previousEvents(s.client, 'GAME', 'DegeneretteBetPlaced', resolved,
    { filters: { player: a.player, index: BigInt(a.index), betId: BigInt(a.betId) }, signal });
  return prior.at(-1)?.args.packed ?? null;
}

export async function playerDay(s, player, day, signal) {
  const range = await activityRange(s, day, signal);
  if (range.fromBlock > range.toBlock) throw new ChainDataError('This day has not started.', 'DAY_NOT_STARTED');
  const [events, questRows, coinflip, level] = await Promise.all([
    eventFacts(s, await knownEvents(['LootBoxBuy', 'DegenesisBuy', ...BOX_RESULTS]).then(names => [...names, 'DegeneretteBetPlaced', 'DegeneretteResolved', 'DeityPassPurchased', 'EntriesBought']), { contract: 'GAME', player, ...range, signal }),
    settlementFacts(s, 'QUESTS', ['QuestProgressUpdated', 'QuestCompleted'], day, { player, signal }),
    coinflipDay(s, day, player, signal), levelAt(s, range.fromBlock, signal),
  ]);
  const quests = new Map();
  for (const row of questRows) {
    const a = row.args; const key = Number(a.slot); const prior = quests.get(key);
    quests.set(key, { slot: key, day, questType: Number(a.questType), progress: a.progress ?? prior?.target ?? null, target: a.target ?? prior?.target ?? null,
      completed: row.name === 'QuestCompleted' || prior?.completed === true });
  }
  return { address: player, day, level, blockNumber: String(range.toBlock), holdings: { entries: null, totalMintedOnLevel: null, balances: [] },
    activity: {
      // Degenesis orders mirror the database: presale=true, no lootboxIndex (they are cohort orders).
      // A queued buy names its (buffer, position); results carry the settlement reference.
      lootboxPurchases: events.filter(e => ['LootBoxBuy', 'DegenesisBuy'].includes(e.name)).map(e => ({ lootboxIndex: e.name === 'DegenesisBuy' ? null
        : Number(boxReference(e.args.index, e.args.position)), ethSpent: e.args.amount, flipSpent: '0', ticketsReceived: null, presale: e.name !== 'LootBoxBuy' })),
      lootboxResults: events.filter(e => BOX_RESULTS.includes(e.name)).map(e => ({ lootboxIndex: e.args.lootboxIndex == null && e.args.index == null ? null : Number(e.args.lootboxIndex ?? e.args.index),
        rewardType: ({ LootBoxOpened: 'opened', DegenesisOrderResolved: 'degenesis_opened' })[e.name] ?? e.name, rewardData: e.args })),
      bets: events.filter(e => e.name === 'DegeneretteBetPlaced').map(e => ({ betIndex: Number(e.args.index), betId: e.args.betId })),
      // One DegeneretteResolved per settled bet carries every spin (no per-spin event).
      betResults: await Promise.all(events.filter(e => e.name === 'DegeneretteResolved').map(async e => ({ betIndex: Number(e.args.index), betId: e.args.betId, resultType: 'resolved',
        payout: String((await import('../app/degenerette.js')).degeneretteTotalPayoutFromChain(e.args.totalPayout, await placementWord(s, e, events, signal))) }))),
      coinflip: coinflip.playerStake == null ? null : { stakeAmount: coinflip.playerStake, win: coinflip.win, rewardPercent: coinflip.rewardPercent },
      craps: null, quests: [...quests.values()], affiliateEarnings: null,
    }, store: { deityPassPurchases: events.filter(e => e.name === 'DeityPassPurchased').map(e => ({ symbolId: Number(e.args.symbolId), price: e.args.price, level: Number(e.args.level) })), levelCatalog: [] } };
}
export async function ticketPacks(s, player, range, signal) {
  const [first, last] = await Promise.all([levelAt(s, range.fromBlock, signal), levelAt(s, range.toBlock, signal)]);
  const packs = new Map();
  // Tickets mint at most two levels ahead (_mintCeiling, audit 26ad5863).
  for (let level = Math.max(0, first - 1); level <= last + 2; level++) {
    const batches = await revealedEntries(s, player, level, { signal });
    for (const row of batches) {
      if (row.blockNumber < range.fromBlock || row.blockNumber > range.toBlock) continue;
      const key = `${row.transactionHash}:${level}`;
      if (!packs.has(key)) packs.set(key, { packId: `tickets-${key}`, revealBlock: String(row.blockNumber), transactionHash: row.transactionHash, level, ord: eventOrdinal(row), traits: [] });
      packs.get(key).traits.push(...row.traits);
    }
  }
  return [...packs.values()].map(({ traits, ...pack }) => {
    const quadrants = [[], [], [], []]; traits.forEach(trait => quadrants[trait >> 6].push(trait));
    const tickets = Array.from({ length: Math.max(...quadrants.map(q => q.length)) }, (_, i) => ({ traits: quadrants.flatMap(q => q[i] == null ? [] : [q[i]]) }));
    return { ...pack, ticketCount: tickets.length, tickets, presentationGrouping: true };
  }).sort((a,b) => b.ord - a.ord);
}
export async function readViewerRoute(s, url, { signal } = {}) {
  const p = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  if (p[0] === 'viewer' && p[1] === 'player' && p[3] === 'day') {
    const player = playerAddress(p[2]); const day = uint(p[4]);
    if (p[5] === 'craps') {
      const { fromBlock } = await activityRange(s, Math.max(1, day - 1), signal);
      const [rows, battleEvents] = await Promise.all([
        eventFacts(s, ['CrapsBetSettled', 'CrapsBattlePaid', 'CrapsHighRollerPaid', 'CrapsProgressivePaid',
          'CrapsHottestShooterPaid', 'HighRollerReserveDrawn', 'CrapsPassesCredited', 'CrapsProtocolAwardSplit',
        ], { contract: 'CRAPS', player, fromBlock, signal }),
        eventFacts(s, ['JackpotBattleLocked', 'JackpotBattleStarted'], { contract: 'CRAPS', fromBlock, signal }),
      ]);
      // The draw's request day owns its jackpot battle. Its slot normally
      // belongs to the previous lobby day (and may be a detached free field).
      // Match the frozen request identity instead of dropping those winnings
      // or counting them again in the slot day's ordinary Craps card.
      const jackpotDays = new Map(battleEvents.filter(row => row.name === 'JackpotBattleLocked')
        .map(row => [String(row.args.slot), Number(row.args.requestDay)]));
      const starts = new Map(battleEvents.filter(row => row.name === 'JackpotBattleStarted')
        .map(row => [String(row.args.slot), eventOrdinal(row)]));
      const slotOf = row => {
        const slot = BigInt(row.args.battleKey ?? row.args.slot ?? (BigInt(row.args.betId) >> 64n));
        // Day tickets reuse their slot-zero bet ID for all seven windows. Once
        // the Main Event starts, their remaining run is in that jackpot field.
        const main = slot + 6n;
        if (row.name === 'CrapsBetSettled' && slot % 8n === 0n
          && starts.has(String(main)) && eventOrdinal(row) > starts.get(String(main))) return main;
        return slot;
      };
      const progressive = new Map();
      const netPayout = new Map();
      const passAwards = [];
      let passCredit = null;
      for (const row of rows) {
        const key = `${row.transactionHash}:${row.args.battleKey}`;
        if (row.name === 'CrapsProgressivePaid') progressive.set(key, row);
        if (row.name === 'CrapsPassesCredited') passCredit = row;
        if (row.name !== 'CrapsProtocolAwardSplit') continue;
        // The progressive event reports gross value before banking its comp
        // slice. Other payout events already report their liquid FLIP credit.
        if (Number(row.args.source) === 4 && progressive.has(key)) {
          netPayout.set(progressive.get(key), BigInt(row.args.liquidFlip));
        }
        // _splitAward emits the actual credited comp count immediately before
        // its battle identity. Never attribute unrelated pass purchases here.
        if (passCredit?.transactionHash === row.transactionHash && Number(passCredit.logIndex) + 1 === Number(row.logIndex)) {
          passAwards.push({ ...row, credit: passCredit.args });
        }
        passCredit = null;
      }
      const mine = rows.filter(row => {
        if (row.name === 'CrapsPassesCredited' || row.name === 'CrapsProtocolAwardSplit') return false;
        if (row.name === 'CrapsHighRollerPaid' && row.args.bankrollRider) return false;
        const slot = slotOf(row);
        return (jackpotDays.get(String(slot)) ?? Number(slot / 8n)) === day;
      });
      // A run, its battle pot and its progressive can all pay the same seat.
      // These are payment events, not three different winning battles.
      const amountOf = row => netPayout.get(row) ?? BigInt(row.args.paid ?? row.args.amount);
      const paid = mine.filter(row => amountOf(row) > 0n);
      const jackpot = paid.filter(row => jackpotDays.get(String(slotOf(row))) === day);
      const total = list => String(list.reduce((sum, row) => sum + amountOf(row), 0n));
      const comps = { normalPasses: 0, highPasses: 0 };
      for (const row of passAwards) {
        if (jackpotDays.get(String(slotOf(row))) === day) {
          comps[row.credit.highRoller ? 'highPasses' : 'normalPasses'] += Number(row.credit.count);
        }
      }
      return { address: player, day, totalWinnings: total(paid), winCount: paid.length, payoutCount: paid.length,
        jackpot: { totalWinnings: total(jackpot), payoutCount: jackpot.length,
          ...(comps.normalPasses > 0 || comps.highPasses > 0 ? comps : {}) } };
    }
    return playerDay(s, player, day, signal);
  }
  if (p[0] === 'player' && ['packs', 'reveals'].includes(p[2])) {
    const player = playerAddress(p[1]);
    if (p[2] === 'packs') {
      const day = uint(q.get('day')); const range = await activityRange(s, day, signal);
      return { address: player, day, blockNumber: String(range.toBlock), lootboxPacks: [], ticketRevealPacks: await ticketPacks(s, player, range, signal) };
    }
    const before = q.has('before') ? uint(q.get('before'), Number.MAX_SAFE_INTEGER) : (s.block.number + 1) * 1_000_000;
    const toBlock = Math.min(s.block.number, Math.floor(before / 1_000_000)); const fromBlock = Math.max(Number(s.client.chain.deployBlock), toBlock - 1_999);
    const packs = (await ticketPacks(s, player, { fromBlock, toBlock }, signal)).filter(pack => pack.ord < before);
    // Keep transaction groups intact; a large buyer's one receipt is one page
    // unit, never a partially sliced cursor that would lose the remaining cards.
    const limit = uint(q.get('limit') ?? 50, 200); const page = packs.slice(0, limit);
    return { address: player, ticketRevealPacks: page, nextCursor: packs.length > limit ? String(page.at(-1).ord) : fromBlock > Number(s.client.chain.deployBlock) ? String(fromBlock * 1_000_000) : null };
  }
  return undefined;
}
